idx = os.path.join(carpeta, "index.html")
app = os.path.join(carpeta, "app.html")
# la mini-app actual se conserva como /app (solo la primera vez)
if not os.path.exists(app):
    if not os.path.exists(idx):
        print("ABORTO: no existe miniapp/index.html"); sys.exit(1)
    shutil.copy(idx, app)
open(os.path.join(carpeta, "web.html"), "wb").write(WEB)

if MARCA in src:
    print("Web actualizada (el codigo ya estaba aplicado). No hace falta reiniciar.")
    sys.exit(0)

BLOQUE = '''
# --- WEB1 ---
_web1_prev = _MiHandler.do_GET

def _web1_get(self):
    p = self.path.split("?")[0]
    f = {"/": "web.html", "/index.html": "web.html", "/app": "app.html", "/app/": "app.html"}.get(p)
    if f:
        try:
            ruta = _mi_os.path.join(_mi_os.path.dirname(_mi_os.path.abspath(__file__)), "miniapp", f)
            b = open(ruta, "rb").read()
            self.send_response(200); self.send_header("Content-Type", "text/html; charset=utf-8")
            self.send_header("Cache-Control", "no-cache"); self.send_header("Content-Length", str(len(b))); self.end_headers(); self.wfile.write(b)
            return
        except Exception as e:
            print("error web", e, flush=True)
    return _web1_prev(self)

_MiHandler.do_GET = _web1_get
'''
marca_main = "if __name__ == \"__main__\":"
nuevo = src.replace(marca_main, BLOQUE + "\n\n" + marca_main, 1)
bak = RUTA + ".bak_web1_" + time.strftime("%Y%m%d%H%M%S")
shutil.copy(RUTA, bak)
tmp = RUTA + ".web1tmp.py"
open(tmp, "w", encoding="utf-8").write(nuevo)
try:
    py_compile.compile(tmp, doraise=True)
except Exception as e:
    os.remove(tmp); print("ABORTO: el codigo no compila, no toco nada:", e); sys.exit(1)
os.replace(tmp, RUTA)
print("Web instalada. Copia de seguridad:", bak)
print("Ahora reinicia: sudo systemctl restart chivato")
